style.css:
@-moz-document regexp("^(chrome|edge)://.*/.*\.pdf.*$"), regexp("^chrome-extension://mhjfbmdgcfjbbpaeojofohoefgiehjai/.*$"), regexp("^file:/.+\.pdf($|\?.*)"), regexp("^https?://.+\.pdf($|\?.*)") {
embed[type="application/pdf"],
  iframe[src*=".pdf"],
  object[type="application/pdf"],
  #viewer,
  .pdfViewer,
  .viewerContainer,
  #mainContainer,
  #outerContainer,
  #toolbarContainer,
  body {
    background: #000 !important;
  }

  /* Main PDF page inversion */
  .pdfViewer,
  #viewer,
  .page,
  canvas {
    filter: invert(1) hue-rotate(180deg) contrast(0.95) brightness(0.92) !important;
  }

  /* Re-invert images/icons that otherwise look wrong */
  img,
  svg,
  .toolbar,
  #toolbarContainer,
  button,
  input {
    filter: invert(1) hue-rotate(180deg) !important;
  }
}

@-moz-document domain("avaindustries.ca") {
iframe[src*=".pdf"],
  object[type="application/pdf"],
  embed[type="application/pdf"] {
    filter: invert(1) hue-rotate(180deg) contrast(0.95) brightness(0.92) !important;
    background: #000 !important;
  }
}
